if { (!exists(global.nxtUserToolsLoadDepth) || global.nxtUserToolsLoadDepth < 1) && (!exists(global.nxtAutoPersistTools) || global.nxtAutoPersistTools) }
    M98 P"nxt-user-tools-sync.g"

; M4002.g: CLEAR ALL USER TOOLS
;
; Removes every defined tool EXCEPT the probe slot (nxtProbeToolID), which is
; regenerated from config at boot and must survive. Used by Tool Library replace import.

if { !inputs[state.thisInput].active }
    M99

if { !exists(global.nxtTT) }
    M99

var prevPersist = true
if { exists(global.nxtAutoPersistTools) }
    set var.prevPersist = { global.nxtAutoPersistTools }
    set global.nxtAutoPersistTools = false

var i = 0
while { var.i < limits.tools }
    if { exists(global.nxtProbeToolID) && var.i == global.nxtProbeToolID }
        set var.i = { var.i + 1 }
        continue
    if { var.i < #tools && tools[var.i] != null }
        M4001 P{var.i}
    set var.i = { var.i + 1 }

if { exists(global.nxtAutoPersistTools) }
    set global.nxtAutoPersistTools = { var.prevPersist }
if { (!exists(global.nxtUserToolsLoadDepth) || global.nxtUserToolsLoadDepth < 1) }
    if { !exists(global.nxtAutoPersistTools) || global.nxtAutoPersistTools }
        M98 P"nxt-user-tools-sync.g"

echo "nxt: tool table cleared (probe slot kept)"

; M4005.g: CHECK nxt POST-PROCESSOR VERSION
;
; Compares param.V from the CAM post-processor to global.nxtVersion (release line, e.g. v0.7.0).
; Exact string match only — no tag or beta-number rules.

if { !inputs[state.thisInput].active }
    M99

if { !exists(param.V) }
    abort { "M4005: post-processor version (V...) is required" }

if { !exists(global.nxtVersion) }
    abort { "M4005: nxt not loaded (global.nxtVersion missing)" }

if { param.V != global.nxtVersion }
    abort { "Post-processor version mismatch: need " ^ global.nxtVersion ^ ", got " ^ param.V }

; M5000.g: GET TOOL-COMPENSATED ABSOLUTE POSITION
;
; Calculates the current tool-compensated absolute machine position
; and stores it in global.nxtAbsPos (all axes) or a single axis value.
;
; P0 — all axes (vector). P1 I<axis> — single axis scalar (Jake-compatible).

; Make sure this file is not executed by the secondary motion system
if { !inputs[state.thisInput].active }
    M99

M400

if { !exists(global.nxtAbsPos) }
    global nxtAbsPos = { vector(#move.axes, null) }

if { !exists(param.P) || param.P == 0 }
    set global.nxtAbsPos = { vector(#move.axes, null) }
    while { iterations < #move.axes }
        var nxtWpOff = { move.axes[iterations].workplaceOffsets[move.workplaceNumber] }
        var nxtToolOff = { state.currentTool < 0 ? 0 : tools[state.currentTool].offsets[iterations] }
        set global.nxtAbsPos[iterations] = { var.nxtWpOff + var.nxtToolOff + move.axes[iterations].userPosition }
    M99

if { param.P == 1 && exists(param.I) && param.I >= 0 && param.I < #move.axes }
    var nxtWpOff1 = { move.axes[param.I].workplaceOffsets[move.workplaceNumber] }
    var nxtToolOff1 = { state.currentTool < 0 ? 0 : tools[state.currentTool].offsets[param.I] }
    set global.nxtAbsPos = { var.nxtWpOff1 + var.nxtToolOff1 + move.axes[param.I].userPosition }
    M99

abort { "M5000: Invalid P parameter (use P0 for all axes, or P1 I<axis> for one axis)." }

; M5010.g: RESET WCS PROBE DETAILS

if { exists(param.W) && param.W != null && (param.W < 0 || param.W >= limits.workplaces) }
    abort { "Work Offset (W..) must be between 0 and " ^ limits.workplaces-1 ^ "!" }

; Default workOffset to the current workplace number if not specified
; with the W parameter.
var workOffset = { (exists(param.W) && param.W != null) ? param.W : move.workplaceNumber }


; WCS Numbers and Offsets are confusing. Work Offset indicates the offset
; from the first work co-ordinate system, so is 0-indexed. WCS number indicates
; the number of the work co-ordinate system, so is 1-indexed.
var wcsNumber = { var.workOffset + 1 }

; Center, Corner, Radius, Surface, Dimensions, Rotation
; 1 2 4 8 16 32

; By default, reset everything
var reset = { exists(param.R) ? param.R : 63 }

; If first bit is set, reset center position
; If second bit is set, reset corner position
; If third bit is set, reset radius
; If fourth bit is set, reset surface position
; If fifth bit is set, reset dimensions
; If sixth bit is set, reset rotation

if { mod(floor(var.reset/pow(2,0)),2) == 1 }
    ; Reset Center
    if { global.nxtTutorialMode }
        echo { "Resetting WCS " ^ var.wcsNumber ^ " probed center"}
    set global.nxtWPCtrPos[var.workOffset] = global.nxtDfltWPCtrPos

if { mod(floor(var.reset/pow(2,1)),2) == 1 }
    ; Reset Corner
    if { global.nxtTutorialMode }
        echo { "Resetting WCS " ^ var.wcsNumber ^ " probed corner"}
    set global.nxtWPCnrPos[var.workOffset] = global.nxtDfltWPCnrPos
    set global.nxtWPCnrDeg[var.workOffset] = global.nxtDfltWPCnrDeg
    set global.nxtWPCnrNum[var.workOffset] = global.nxtDfltWPCnrNum

if { mod(floor(var.reset/pow(2,2)),2) == 1}
    ; Reset Radius
    if { global.nxtTutorialMode }
        echo { "Resetting WCS " ^ var.wcsNumber ^ " probed radius"}
    set global.nxtWPRad[var.workOffset] = global.nxtDfltWPRad

if { mod(floor(var.reset/pow(2,3)),2) == 1 }
    ; Reset Surface
    if { global.nxtTutorialMode }
        echo { "Resetting WCS " ^ var.wcsNumber ^ " probed surface"}
    set global.nxtWPSfcAxis[var.workOffset] = global.nxtDfltWPSfcAxis
    set global.nxtWPSfcPos[var.workOffset] = global.nxtDfltWPSfcPos

if { mod(floor(var.reset/pow(2,4)),2) == 1 }
    ; Reset Dimensions
    if { global.nxtTutorialMode }
        echo { "Resetting WCS " ^ var.wcsNumber ^ " probed dimensions"}
    set global.nxtWPDims[var.workOffset] = global.nxtDfltWPDims
    set global.nxtWPDimsErr[var.workOffset] = global.nxtDfltWPDimsErr

if { mod(floor(var.reset/pow(2,5)),2) == 1 }
    ; Reset Rotation
    if { global.nxtTutorialMode }
        echo { "Resetting WCS " ^ var.wcsNumber ^ " probed rotation"}
    set global.nxtWPDeg[var.workOffset] = global.nxtDfltWPDeg

; M5013.g — set per-axis maintenance service threshold (mm)
; Usage: M5013 A<axisIndex> S<thresholdMm>
; Ensures nxtAxisServiceAt exists and is large enough before writing.
; Needed when nxt-vars.g ran before M584 and sized the vector to 0.

if { !exists(param.A) || param.A == null || param.A < 0 }
    abort { "M5013: need A<axisIndex> >= 0" }

if { !exists(param.S) || param.S == null || param.S < 0 }
    abort { "M5013: need S<thresholdMm> >= 0" }

var nxtIdx = { floor(param.A) }
var nxtNeed = { var.nxtIdx + 1 }
var nxtLen = { max(#move.axes, var.nxtNeed) }
set var.nxtLen = { max(var.nxtLen, 4) }

if { !exists(global.nxtAxisServiceAt) }
    global nxtAxisServiceAt = { vector(var.nxtLen, 0.0) }
elif { #global.nxtAxisServiceAt < var.nxtLen }
    var nxtOld = { global.nxtAxisServiceAt }
    set global.nxtAxisServiceAt = { vector(var.nxtLen, 0.0) }
    var nxtCopy = 0
    while { var.nxtCopy < #var.nxtOld }
        set global.nxtAxisServiceAt[var.nxtCopy] = { var.nxtOld[var.nxtCopy] }
        set var.nxtCopy = { var.nxtCopy + 1 }

set global.nxtAxisServiceAt[var.nxtIdx] = { param.S }
M99

; M5014.g: CALIBRATION PHASE-1 — INDICATOR ZERO / TRAVEL / RETURN (backlash estimate)
;
; Zero dial on block face → away by 8/16/24 → return same distance → enter residual.
; measured = commanded - residual → global.nxtCalTravelCmd / nxtCalTravelMeas
; Round-trip isolates lost motion (backlash), not steps/mm — use Phase 2 for M92.
;
; USAGE: M5014 X0|Y0|Z0|A0 D<±1> [R<1|3>] [F<feed>]
;   D = away direction along the axis (+1 or -1)
;   R = repeats per leg (1 default, or 3); mean residual used when R>1

if { !inputs[state.thisInput].active }
    M99

var axisParams = { null, null, null, null }
if { exists(param.X) }
    set var.axisParams[0] = param.X
if { exists(param.Y) }
    set var.axisParams[1] = param.Y
if { exists(param.Z) }
    set var.axisParams[2] = param.Z
if { exists(param.A) }
    set var.axisParams[3] = param.A

var axisIdx = -1
while { iterations < #var.axisParams }
    if { var.axisParams[iterations] != null }
        if { var.axisIdx != -1 }
            abort { "M5014: Specify exactly one of X, Y, Z, or A" }
        set var.axisIdx = { iterations }

if { var.axisIdx < 0 }
    abort { "M5014: Specify exactly one of X, Y, Z, or A" }

if { !exists(param.D) || param.D == null || param.D == 0 }
    abort { "M5014: D must be +1 or -1 (away from the measured face)" }

var dirAway = { param.D > 0 ? 1 : -1 }

if { var.axisIdx >= #move.axes || !move.axes[var.axisIdx].visible }
    abort { "M5014: Selected axis is not available" }

var letter = { move.axes[var.axisIdx].letter }
var repeats = { 1 }
if { exists(param.R) && param.R != null && param.R >= 3 }
    set var.repeats = 3

var feed = { exists(param.F) ? param.F : 300 }
if { exists(global.nxtManualProbeFeeds) && #global.nxtManualProbeFeeds > 1 }
    set var.feed = { exists(param.F) ? param.F : global.nxtManualProbeFeeds[1] }

G90
G21
G94

var jogA = { "Align indicator on the " ^ var.letter ^ " face (away dir " }
var jogB = { var.jogA ^ var.dirAway ^ "). Zero the dial, then OK." }
var jogC = { var.jogB ^ "<br/><b>CAUTION</b>: Jogging does not watch probes." }
M291 P{var.jogC} R"nxt: Calibration P1" X1 Y1 Z1 J1 T0 S3
if { result != 0 }
    abort { "M5014: Operator cancelled before test" }

M5000 P0
var startPos = { global.nxtAbsPos }

if { !exists(global.nxtCalTravelCmd) || global.nxtCalTravelCmd == null }
    global nxtCalTravelCmd = { vector(3, 0.0) }
if { !exists(global.nxtCalTravelMeas) || global.nxtCalTravelMeas == null }
    global nxtCalTravelMeas = { vector(3, 0.0) }
if { !exists(global.nxtCalTravelAxis) }
    global nxtCalTravelAxis = null

set global.nxtCalTravelCmd[0] = 8
set global.nxtCalTravelCmd[1] = 16
set global.nxtCalTravelCmd[2] = 24
set global.nxtCalTravelMeas[0] = 0
set global.nxtCalTravelMeas[1] = 0
set global.nxtCalTravelMeas[2] = 0
set global.nxtCalTravelAxis = { var.letter }

var distances = { 8, 16, 24 }
var leg = 0
while { var.leg < 3 }
    var dCmd = { var.distances[var.leg] }
    var sumR = { 0 }
    var rep = 0
    while { var.rep < var.repeats }
        ; Return to start before each cycle
        if { var.axisIdx == 0 }
            G53 G1 X{var.startPos[0]} F{var.feed}
        elif { var.axisIdx == 1 }
            G53 G1 Y{var.startPos[1]} F{var.feed}
        elif { var.axisIdx == 2 }
            G53 G1 Z{var.startPos[2]} F{var.feed}
        else
            G53 G1 A{var.startPos[3]} F{var.feed}
        M400

        var away = { var.dirAway * var.dCmd }
        var back = { 0 - var.away }
        G91
        if { var.axisIdx == 0 }
            G1 X
; … truncated for dataset …

; M5015.g: CALIBRATION G6512 — JOG, PROBE, RETURN
;
; Jog to approach → G6512 to target → return to approach position.
; USAGE: M5015 X|Y|Z<target> I<probeId>
; Target is machine coordinate for the probe move (may be negative).

if { !inputs[state.thisInput].active }
    M99

var axisParams = { null, null, null }
if { exists(param.X) }
    set var.axisParams[0] = param.X
if { exists(param.Y) }
    set var.axisParams[1] = param.Y
if { exists(param.Z) }
    set var.axisParams[2] = param.Z

var axisIdx = -1
var target = 0
while { iterations < #var.axisParams }
    if { var.axisParams[iterations] != null }
        if { var.axisIdx != -1 }
            abort { "M5015: Specify exactly one of X, Y, or Z" }
        set var.axisIdx = { iterations }
        set var.target = { var.axisParams[iterations] }

if { var.axisIdx < 0 }
    abort { "M5015: Specify exactly one of X, Y, or Z as the probe target" }

if { !exists(param.I) || param.I == null }
    abort { "M5015: Probe ID I.. is required" }

var letter = { move.axes[var.axisIdx].letter }

var jogMsgA = { "Jog near the measuring surface for " ^ var.letter }
var jogMsgB = { var.jogMsgA ^ ", then press OK.<br/><b>CAUTION</b>: Jogging does not watch the probe." }
M291 P{var.jogMsgB} R"nxt: Calibration probe" X1 Y1 Z1 J1 T0 S3
if { result != 0 }
    abort { "M5015: Operator cancelled before probe" }

M5000 P0
var approach = { global.nxtAbsPos }

if { var.axisIdx == 0 }
    G6512 X{var.target} I{param.I}
elif { var.axisIdx == 1 }
    G6512 Y{var.target} I{param.I}
else
    G6512 Z{var.target} I{param.I}

; G6512 already backs off by dive height; return to pre-probe approach
var feed = { 600 }
if { exists(global.nxtManualProbeFeeds) && #global.nxtManualProbeFeeds > 0 }
    set var.feed = { global.nxtManualProbeFeeds[0] }

G90
if { var.axisIdx == 0 }
    G53 G1 X{var.approach[0]} F{var.feed}
elif { var.axisIdx == 1 }
    G53 G1 Y{var.approach[1]} F{var.feed}
else
    G53 G1 Z{var.approach[2]} F{var.feed}
M400

echo { "M5015: Probe done; returned to approach. Capture nxtLastProbeResult in Calibration." }

; M5016.g: STATIC DATUM SETUP (toolsetter + probe reference)
;
; One-time geometry: toolsetter Z_act, reference Z_ref, nxtDeltaMachine = Z_ref - Z_act.
; USAGE: M5016
; Requires: nxtFeatureTouchProbe, nxtFeatureToolSetter, nxtTouchProbeID, nxtToolSetterID.
; After success: park (G27) and T{nxtProbeToolID} from the Calibration UI so tpost runs G6511.

if { !inputs[state.thisInput].active }
    M99

if { !global.nxtFeatureTouchProbe || !global.nxtFeatureToolSetter }
    abort { "M5016: Touch probe and toolsetter features must be enabled" }

if { global.nxtTouchProbeID == null }
    abort { "M5016: nxtTouchProbeID is not configured" }

if { global.nxtToolSetterID == null }
    abort { "M5016: nxtToolSetterID is not configured" }

G90
G21
G94

; --- 1. Install datum tool ---
var msgDatum = "Install a rigid datum tool (gauge pin) in the spindle, then press OK."
M291 P{var.msgDatum} R"nxt: Datum setup" S3
if { result != 0 }
    abort { "M5016: Cancelled — install datum tool" }

; --- 2. Jog over toolsetter ---
var msgTsA = "Jog the datum tool over the center of the toolsetter."
var msgTsB = { var.msgTsA ^ "<br/><b>CAUTION</b>: Jogging does not watch probes. Leave Z clear above the platen." }
M291 P{var.msgTsB} R"nxt: Datum setup" X1 Y1 Z1 J1 T0 S3
if { result != 0 }
    abort { "M5016: Cancelled before toolsetter probe" }

M5000 P0
var tsX = { global.nxtAbsPos[0] }
var tsY = { global.nxtAbsPos[1] }
var tsZ = { global.nxtAbsPos[2] }

var tsTravel = { 80.0 }
if { exists(global.nxtToolSetterProbeTravelMm) && global.nxtToolSetterProbeTravelMm > 0 }
    set var.tsTravel = { global.nxtToolSetterProbeTravelMm }
var tsProbeTargetZ = { var.tsZ - var.tsTravel }

; --- 3. Probe toolsetter with datum ---
echo "M5016: Probing toolsetter at X=" ^ var.tsX ^ " Y=" ^ var.tsY
G53 G0 X{var.tsX} Y{var.tsY}
G6512 Z{var.tsProbeTargetZ} I{global.nxtToolSetterID}
var zAct = { global.nxtLastProbeResult }

set global.nxtToolSetterPos = { var.tsX, var.tsY, var.zAct }
echo "M5016: nxtToolSetterPos = {" ^ var.tsX ^ ", " ^ var.tsY ^ ", " ^ var.zAct ^ "}"

; Park Z before moving to reference surface
G27 Z1

; --- 4. Jog datum onto probe reference surface ---
var msgRefA = "Jog the datum tool onto the touch-probe reference surface."
var msgRefB = { var.msgRefA ^ "<br/>Touch the surface with the datum tip, then press OK to store XYZ." }
M291 P{var.msgRefB} R"nxt: Datum setup" X1 Y1 Z1 J1 T0 S3
if { result != 0 }
    abort { "M5016: Cancelled before reference surface" }

M5000 P0
var refX = { global.nxtAbsPos[0] }
var refY = { global.nxtAbsPos[1] }
var refZ = { global.nxtAbsPos[2] }

set global.nxtTouchProbeRefPos = { var.refX, var.refY, var.refZ }
echo "M5016: nxtTouchProbeRefPos = {" ^ var.refX ^ ", " ^ var.refY ^ ", " ^ var.refZ ^ "}"

; --- 5. Static datum ---
set global.nxtDeltaMachine = { var.refZ - var.zAct }
echo "M5016: nxtDeltaMachine = " ^ global.nxtDeltaMachine ^ " mm (Z_ref - Z_act)"

G27 Z1

var msgDoneA = "Static datum saved. Next: use Calibration to park,"
var msgDoneB = { var.msgDoneA ^ " install the touch probe, and load the probe tool." }
M291 P{var.msgDoneB} R"nxt: Datum setup" S2

echo "M5016: Datum setup complete — continue in Calibration UI"

; M6515.g: CHECK MACHINE LIMITS
